def main():
    apply = "--apply" in sys.argv
    for f in FILES:
        if not os.path.isfile(_p(f)):
            print("ABORT: %s not found." % f)
            return 1

    admin = "frontend/web/src/pages/AdminConfig.tsx"
    cur = open(_p(admin), encoding="utf-8").read()
    if "PoolVisibilityPanel" in cur:
        print("ABORT: PV1 looks applied.")
        return 1

    for f, new in FILES.items():
        c = open(_p(f), encoding="utf-8").read()
        for m in ("CommitteeTiersPanel", "BranchesPanel", "Business Lines",
                  "escalateToChief", "castCommitteeVote"):
            if c.count(m) and not new.count(m):
                print("ABORT: %r is in %s and NOT in this patch." % (m, os.path.basename(f)))
                return 1
    print("  ok  nothing present would be removed")

    a = FILES[admin]
    if "label: 'Credit Pool Access'" not in a:
        print("ABORT: the section is not in the tab list.")
        return 1
    if "subTab === 'pool'" not in a:
        print("ABORT: the section is listed but never rendered.")
        return 1
    if "getPoolVisibility" not in a or "setPoolVisibility" not in a:
        print("ABORT: the panel does not read or write the config.")
        return 1
    if "every credit screen will be empty" not in a:
        print("ABORT: an empty list would look like a working default rather")
        print("       than nobody having access.")
        return 1
    for f, new in FILES.items():
        for op, cl in (("{", "}"), ("(", ")")):
            if new.count(op) != new.count(cl):
                print("ABORT: %s unbalanced %s%s." % (os.path.basename(f), op, cl))
                return 1
    print("  ok  post-checks: listed, rendered, wired, honest when empty")

    if not apply:
        print("\nDRY RUN - nothing written. Re-run with --apply.")
        return 0

    for f, new in FILES.items():
        shutil.copy2(_p(f), _p(f) + BACKUP_SUFFIX)
        open(_p(f), "w", encoding="utf-8", newline="").write(new)
        print("APPLIED %s" % f)
    print("\nNext: pushd frontend\\web && pnpm tsc --noEmit && pnpm build && popd")
    print("Administration > Credit Pool Access.")
    return 0


if __name__ == "__main__":
    sys.exit(main())
